// Local wall times for the geo entry: the local clock (src/geo/local-clock.ts), and the host check of a wall
// time the host's Intl read (docs/time.md, "Host time zone data"), with its probe table
// (src/geo/host-probes-data.ts, generated by scripts/build-host-zone-probes.mjs).
import type { BirthInput } from "../types.js";
import { validateBirthSettings } from "../birth-input.js";
import { HOST_PROBES, HOST_PROBES_TZDB, HOST_PROBES_UNTIL } from "./host-probes-data.js";
import { DAY, FIXED_ZONE, PROBE, currentHost, readLocalTime } from "./local-clock.js";
import type { Host, HostZoneCheck, LocalBirthInput, LocalTimeOptions, LocalTimeResolution } from "./local-clock.js";
import { nameHash } from "./zone-history.js";

export { ZoneHistoryNotLoadedError, offsetAt, prepareLocalTime, readLocalTime, setHostForTests, zoneOffsetAt } from "./local-clock.js";
export type {
  FoldChoice,
  HostZoneCheck,
  LocalBirthInput,
  LocalTimeOptions,
  LocalTimeResolution,
  TransitionCause,
  ZoneTransition
} from "./local-clock.js";

/** The host's answer at each probe, seconds east, by lower-cased zone name and probe instant, per host. */
const hostAnswers = new WeakMap<Host, Map<string, number>>();

/** An open-ended span's probe is this long after its start, as scripts/build-host-zone-probes.mjs places it. */
const OPEN_PROBE = 45 * DAY;
/**
 * HOST_PROBES decoded once: per name hash, [from, to, probe] ms and the offset s, flat. An open-ended span ends
 * at HOST_PROBES_UNTIL, where the two releases stop being compared: past it, an older host may agree again.
 */
let probeTable: Map<number, number[]> | null = null;

function probeSpans(timeZone: string): readonly number[] | undefined {
  if (!probeTable) {
    probeTable = new Map();
    for (const row of HOST_PROBES.split(";")) {
      const [hashes = "", body = ""] = row.split(":");
      const minutes = body.split(",").map((value) => parseInt(value, 36) * 60_000);
      const spans: number[] = [];
      let previous = 0;
      for (let index = 0; index + 2 < minutes.length; index += 3) {
        const from = previous + minutes[index]!;
        const length = minutes[index + 1]!;
        spans.push(from, length ? from + length : HOST_PROBES_UNTIL, from + (length ? Math.floor(length / 120_000) * 60_000 : OPEN_PROBE), minutes[index + 2]! / 1000);
        previous = length ? from + length : from;
      }
      for (const hash of hashes.split(",")) probeTable.set(parseInt(hash, 36), spans);
    }
  }
  return probeTable.get(nameHash(timeZone));
}

/**
 * The host check of an instant the host's Intl answered: each span of the zone within PROBE of the instant has
 * its probe asked once (remembered) and compared with the pinned offset.
 */
export function checkHost(timeZone: string, utcMs: number): HostZoneCheck {
  const spans = utcMs >= 0 && !FIXED_ZONE.test(timeZone) ? probeSpans(timeZone) : undefined;
  const host = currentHost();
  let answers = hostAnswers.get(host);
  if (!answers) hostAnswers.set(host, (answers = new Map()));
  let agreed: HostZoneCheck | null = null;
  for (let index = 0; spans && index < spans.length; index += 4) {
    if (utcMs < spans[index]! - PROBE || utcMs >= spans[index + 1]! + PROBE) continue;
    const probe = spans[index + 2]!;
    const pinned = spans[index + 3]!;
    const key = `${timeZone.toLowerCase()}\n${probe}`;
    let answer = answers.get(key);
    if (answer === undefined) {
      answer = Math.round(host.offsetAt(timeZone, probe) * 60);
      answers.set(key, answer);
    }
    const version = host.tzdbVersion();
    const status = answer === pinned ? "current" : version !== null && version > HOST_PROBES_TZDB ? "newer" : "differs";
    const check: HostZoneCheck = {
      status,
      probe: new Date(probe).toISOString(),
      hostOffsetMinutes: answer / 60,
      tzdbOffsetMinutes: pinned / 60,
      tzdbVersion: HOST_PROBES_TZDB
    };
    if (status !== "current") return check;
    agreed ??= check;
  }
  return agreed ?? { status: "unchecked" };
}

/**
 * Resolve a local wall time in an IANA zone to UTC: a repeated one takes the
 * earlier instant, or the later one with `options.fold` "later"; a skipped
 * one moves forward by the jump. Before 1970 the
 * shipped tzdb 2025c history answers, loaded by `prepareLocalTime` (a wall
 * time before 1970-01-02 throws otherwise); from 1970, and in the fixed Etc
 * zones, the host's Intl, whose offset near the instant is checked against the
 * pinned tzdb release (`zone.hostCheck`, flag "host-zone-data-differs").
 */
export function resolveLocalToUtc(
  date: string,
  time: string,
  timeZone: string,
  options?: LocalTimeOptions
): LocalTimeResolution {
  const resolution = readLocalTime(date, time, timeZone, options);
  if (resolution.zone.source === "intl") {
    // The host's answer is kept: one probe cannot carry a zone's rules, so the flag reports, it does not correct.
    const check = checkHost(timeZone, resolution.utc.getTime());
    resolution.zone.hostCheck = check;
    if (check.status === "differs") resolution.flags.push("host-zone-data-differs");
  }
  return resolution;
}

const LOCAL_BIRTH_KEYS = [
  "date",
  "time",
  "timeZone",
  "latitude",
  "longitude",
  "houseSystem",
  "timeKnown",
  "calendar",
  "country",
  "fold"
] as const;

/** A local birth resolved, with how its wall time was read and the receipt's `reference`. */
export interface LocalBirthResolution {
  birth: BirthInput;
  resolution: LocalTimeResolution;
  reference: "supplied-instant" | "local-noon";
}

/** Convert a local birth form into the core input, keeping how its wall time was read. */
export function resolveLocalBirth(input: LocalBirthInput): LocalBirthResolution {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new RangeError("birth must be an object containing a local date and timezone.");
  }
  for (const key of Object.getOwnPropertyNames(input)) {
    if (!(LOCAL_BIRTH_KEYS as readonly string[]).includes(key)) throw new RangeError(`Unknown local birth field "${key}".`);
  }
  // One read of each field.
  const fields = Object.fromEntries(LOCAL_BIRTH_KEYS.map((key) => [key, input[key]])) as unknown as LocalBirthInput;
  const settings = validateBirthSettings(fields);
  const { time, calendar, country, fold } = fields;
  const timeKnown = settings.timeKnown ?? time !== undefined;
  if (timeKnown && time === undefined) {
    throw new RangeError("time is required when timeKnown is true.");
  }
  const resolution = resolveLocalToUtc(fields.date, time === undefined ? "12:00" : time, fields.timeZone, {
    longitude: settings.longitude,
    calendar,
    country,
    fold
  });
  return {
    birth: {
      utc: resolution.utc,
      timeKnown,
      houseSystem: settings.houseSystem ?? "whole",
      flags: resolution.flags,
      ...(settings.latitude === undefined ? {} : { latitude: settings.latitude, longitude: settings.longitude })
    },
    resolution,
    reference: time === undefined ? "local-noon" : "supplied-instant"
  };
}

/** Convert a local birth form into the explicit UTC input accepted by the core. */
export function resolveBirth(input: LocalBirthInput): BirthInput {
  return resolveLocalBirth(input).birth;
}
